func (q *Queries) ApplyMarginSettlementsStream(ctx context.Context, seq iter.Seq2[MarginSettlement, error]) (sql.Result, error) {
	chunkCap := min(256, q.cache.MaxRowsPerBatch(sqlDialect, 0, 8))
	bufPtr := marginSettlementChunkPool.Get().(*[]MarginSettlement)
	chunk := (*bufPtr)[:0]
	defer func() {
		clear(chunk)
		*bufPtr = chunk[:0]
		marginSettlementChunkPool.Put(bufPtr)
	}()
	var batchRes runtime.BatchExecResult
	flushChunk := func() error {
		if len(chunk) == 0 {
			return nil
		}
		res, err := q.ApplyMarginSettlementsBatch(ctx, chunk)
		if err != nil {
			return err
		}
		batchRes.Add(res)
		chunk = chunk[:0]
		return nil
	}
	for item, err := range seq {
		if err != nil {
			return nil, err
		}
		chunk = append(chunk, item)
		if len(chunk) >= chunkCap {
			if err := flushChunk(); err != nil {
				return nil, err
			}
		}
	}
	if err := flushChunk(); err != nil {
		return nil, err
	}
	return batchRes, nil
}

